def shortestCover(s):
    n = len(s)
    pi = [0] * n
    k = 0
    for i in range(1, n):
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    cover = [0] * (n + 1)
    last = [0] * (n + 1)
    for L in range(1, n + 1):
        cover[L] = L
        b = pi[L - 1]
        if b:
            c = cover[b]
            if L - last[c] <= c:
                cover[L] = c
                last[c] = L
                continue
        last[L] = L
    return cover[n]
